class Solution {
public:
    int maxSubArrayLen(vector<int>& nums, int k) {
        unordered_map<long long, int> prefixMap;
        prefixMap[0] = -1;
        long long currSum = 0;
        int maxLen = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            currSum += nums[i];
            if (prefixMap.count(currSum - k)) {
                maxLen = max(maxLen, i - prefixMap[currSum - k]);
            }
            if (!prefixMap.count(currSum)) {
                prefixMap[currSum] = i;
            }
        }
        return maxLen;
    }
};

class Solution {
    public int maxSubArrayLen(int[] nums, int k) {
        Map<Long, Integer> prefixMap = new HashMap<>();
        prefixMap.put(0L, -1);
        long currSum = 0;
        int maxLen = 0;
        for (int i = 0; i < nums.length; i++) {
            currSum += nums[i];
            if (prefixMap.containsKey(currSum - k)) {
                maxLen = Math.max(maxLen, i - prefixMap.get(currSum - k));
            }
            if (!prefixMap.containsKey(currSum)) {
                prefixMap.put(currSum, i);
            }
        }
        return maxLen;
    }
}

