var maxSubArrayLen = function(nums, k) {
    const prefixMap = new Map();
    prefixMap.set(0, -1);
    let currSum = 0;
    let maxLen = 0;
    for (let i = 0; i < nums.length; i++) {
        currSum += nums[i];
        if (prefixMap.has(currSum - k)) {
            maxLen = Math.max(maxLen, i - prefixMap.get(currSum - k));
        }
        if (!prefixMap.has(currSum)) {
            prefixMap.set(currSum, i);
        }
    }
    return maxLen;
};
